	if err != nil {
		t.Fatal(err)
	}

	mkDiag := func(eid ID, content string) ID {
		t.Helper()
		r, err := s.CreateDraft(doc, pid, eid, Diagnosis, content)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := s.ActivateRecord(doc, r.ID); err != nil {
